B.c8D=new A.n("Steady! Guard the general!","V\u1eefng v\xe0ng! B\u1ea3o v\u1ec7 t\u01b0\u1edbng!")
B.cdz=new A.n("A check. I have seen worse.","Chi\u1ebfu t\u01b0\u1edbng \xe0. Ta t\u1eebng g\u1eb7p tr\u1eadn c\xf2n kh\xf3 h\u01a1n.")
B.cgs=new A.n("Hold the palace!","Gi\u1eef v\u1eefng c\u1eedu cung!")
B.bju=s([B.c8D,B.cdz,B.cgs],t.g)
B.cbj=new A.n("A costly loss. It will not happen twice.","M\u1ed9t t\u1ed5n th\u1ea5t \u0111\u1eaft gi\xe1. S\u1ebd kh\xf4ng c\xf3 l\u1ea7n th\u1ee9 hai.")
B.cdC=new A.n("Fall back and regroup!","Lui l\u1ea1i, ch\u1ec9nh \u0111\u1ed1n h\xe0ng ng\u0169!")
B.cfI=new A.n("You will pay for that piece.","Ng\u01b0\u01a1i s\u1ebd ph\u1ea3i tr\u1ea3 gi\xe1 cho qu\xe2n c\u1edd \u0111\xf3.")
B.bM1=s([B.cbj,B.cdC,B.cfI],t.g)
B.cc1=new A.n("Left unguarded? Then it is mine.","B\u1ecf tr\u1ed1ng \u01b0? V\u1eady th\xec n\xf3 l\xe0 c\u1ee7a ta.")
B.c87=new A.n("Every gap in your line, I will find.","M\u1ecdi k\u1ebd h\u1edf trong h\xe0ng ng\u0169 ng\u01b0\u01a1i, ta \u0111\u1ec1u t\xecm ra.")
B.cbb=new A.n("One fewer to stand against me.","B\u1edbt \u0111i m\u1ed9t k\u1ebb c\u1ea3n \u0111\u01b0\u1eddng ta.")
B.bp_=s([B.cc1,B.c87,B.cbb],t.g)
B.c6n=new A.n("That was not the way.","N\u01b0\u1edbc \u0111i \u0111\xf3 kh\xf4ng \u0111\xfang r\u1ed3i.")
B.c53=new A.n("You lost the thread. Find it again.","Ng\u01b0\u01a1i l\u1ea1c m\u1ea1ch r\u1ed3i. T\xecm l\u1ea1i \u0111i.")
B.bF6=s([B.c6n,B.c53],t.g)
B.cfz=new A.n("Well fought. I yield the field.","\u0110\xe1nh hay l\u1eafm. Ta xin nh\u01b0\u1eddng tr\u1eadn \u0111\u1ecba.")
B.cfp=new A.n("Retreat! Sound the retreat!","R\xfat qu\xe2n! Th\u1ed5i k\xe8n r\xfat qu\xe2n!")
B.bBe=s([B.cfz,B.cfp],t.g)
B.cfv=new A.n("Train harder, and come again.","H\xe3y luy\u1ec7n th\xeam r\u1ed3i quay l\u1ea1i.")
B.ccG=new A.n("The field is mine today.","H\xf4m nay tr\u1eadn \u0111\u1ecba thu\u1ed9c v\u1ec1 ta.")
B.bnU=s([B.cfv,B.ccG],t.g)
