B.c8_=new A.n(u.BR,"Tr\u01b0\u1eddng th\xe0nh \u0111\xe3 qua nh\u1eefng c\u01a1n b\xe3o d\u1eef h\u01a1n th\u1ebf n\xe0y.")
B.caI=new A.n("Man the ramparts!","L\xean t\u01b0\u1eddng th\xe0nh!")
B.bR4=s([B.c8_,B.caI],t.g)
B.cgj=new A.n("One watchtower falls. The wall is long.","M\u1ed9t v\u1ecdng l\xe2u \u0111\u1ed5. B\u1ee9c t\u01b0\u1eddng c\xf2n d\xe0i l\u1eafm.")
B.c9L=new A.n("Bricks can be laid again.","G\u1ea1ch \u0111\u1ed5 th\xec x\xe2y l\u1ea1i.")
B.bmO=s([B.cgj,B.c9L],t.g)
B.c8e=new A.n("Nothing crosses my frontier unpunished.","Kh\xf4ng k\u1ebb n\xe0o v\u01b0\u1ee3t bi\xean c\u01b0\u01a1ng c\u1ee7a ta m\xe0 kh\xf4ng b\u1ecb tr\u1eebng ph\u1ea1t.")
B.cfC=new A.n("The north wind takes another.","Gi\xf3 b\u1ea5c l\u1ea1i cu\u1ed1n \u0111i th\xeam m\u1ed9t k\u1ebb.")
B.bks=s([B.c8e,B.cfC],t.g)
B.c6Q=new A.n("So the wall has a gate after all.","H\xf3a ra tr\u01b0\u1eddng th\xe0nh c\u0169ng c\xf3 c\u1eeda.")
B.blQ=s([B.c6Q],t.g)
B.c8Q=new A.n("As I said. The wall still stands.","Nh\u01b0 ta \u0111\xe3 n\xf3i. Tr\u01b0\u1eddng th\xe0nh v\u1eabn \u0111\u1ee9ng v\u1eefng.")
B.btU=s([B.c8Q],t.g)
