B.c6G=new A.n(u.oX,"M\u1ed9t \u0111\xf2n t\xe1o b\u1ea1o. K\u1ebb t\xe1o b\u1ea1o th\u01b0\u1eddng ng\xe3 tr\u01b0\u1edbc ti\xean.")
B.c5I=new A.n(u.cB,"Ng\u01b0\u01a1i g\xf5 c\u1eeda th\xe0nh ta? L\xednh g\xe1c c\u1ee7a ta \u0111\xe3 nghe ti\u1ebfng g\xf5 \u1ea5y nhi\u1ec1u l\u1ea7n r\u1ed3i.")
B.bso=s([B.c6G,B.c5I],t.g)
B.c5u=new A.n("One general lost. I have a hundred more.","M\u1ea5t m\u1ed9t t\u01b0\u1edbng. Ta c\xf2n c\u1ea3 tr\u0103m ng\u01b0\u1eddi kh\xe1c.")
